-- ===========================================================================
-- Part 2: CHECK constraints and triggers (hand-written)
-- ===========================================================================

-- Shared vocabulary for verification_status (knowledge and questions):
--   draft      imported or generated, not yet checked
--   in_review  waiting for a reviewer
--   verified   checked against its source; the only status ever served
--   rejected   checked and wrong; kept for the audit trail

-- game_levels
ALTER TABLE "game_levels"
    ADD CONSTRAINT "game_levels_number_range" CHECK ("number" BETWEEN 1 AND 99),
    ADD CONSTRAINT "game_levels_code_format" CHECK ("code" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "game_levels_score_multiplier_range" CHECK ("score_multiplier" > 0 AND "score_multiplier" <= 100),
    ADD CONSTRAINT "game_levels_categories_is_array" CHECK (jsonb_typeof("categories") = 'array'),
    ADD CONSTRAINT "game_levels_unlock_rule_is_object" CHECK (jsonb_typeof("unlock_rule") = 'object'),
    ADD CONSTRAINT "game_levels_completion_rule_is_object" CHECK (jsonb_typeof("completion_rule") = 'object'),
    ADD CONSTRAINT "game_levels_session_config_is_object" CHECK (jsonb_typeof("session_config") = 'object');

-- user_level_unlocks
ALTER TABLE "user_level_unlocks"
    ADD CONSTRAINT "user_level_unlocks_source_valid" CHECK ("source" IN ('rule', 'admin', 'achievement'));

-- game_sessions (v2 columns; NULL on pre-v2 rows)
ALTER TABLE "game_sessions"
    ADD CONSTRAINT "game_sessions_score_multiplier_positive" CHECK ("score_multiplier" IS NULL OR "score_multiplier" > 0),
    ADD CONSTRAINT "game_sessions_rounds_planned_positive" CHECK ("rounds_planned" IS NULL OR "rounds_planned" > 0),
    ADD CONSTRAINT "game_sessions_scoring_rules_is_object" CHECK ("scoring_rules" IS NULL OR jsonb_typeof("scoring_rules") = 'object');

-- game_results (v2 columns; NULL on pre-v2 rows)
ALTER TABLE "game_results"
    ADD CONSTRAINT "game_results_base_score_non_negative" CHECK ("base_score" IS NULL OR "base_score" >= 0),
    ADD CONSTRAINT "game_results_score_multiplier_positive" CHECK ("score_multiplier" IS NULL OR "score_multiplier" > 0),
    ADD CONSTRAINT "game_results_multiplier_with_base" CHECK (("base_score" IS NULL) = ("score_multiplier" IS NULL));

-- game_answers
ALTER TABLE "game_answers"
    ADD CONSTRAINT "game_answers_round_index_non_negative" CHECK ("round_index" >= 0),
    ADD CONSTRAINT "game_answers_question_version_positive" CHECK ("question_version" >= 1),
    ADD CONSTRAINT "game_answers_correct_answers_is_array" CHECK (jsonb_typeof("correct_answers") = 'array'),
    ADD CONSTRAINT "game_answers_score_multiplier_positive" CHECK ("score_multiplier" > 0),
    ADD CONSTRAINT "game_answers_fraction_range" CHECK ("fraction" IS NULL OR "fraction" BETWEEN 0 AND 1),
    ADD CONSTRAINT "game_answers_points_non_negative" CHECK (
        ("base_points" IS NULL OR "base_points" >= 0) AND ("streak_bonus" IS NULL OR "streak_bonus" >= 0)
        AND ("points" IS NULL OR "points" >= 0) AND ("response_ms" IS NULL OR "response_ms" >= 0)),
    -- An answered round has an answer and a score; an open round has neither.
    ADD CONSTRAINT "game_answers_answered_consistently" CHECK (
        ("answered_at" IS NULL) = ("answer" IS NULL)
        AND ("answered_at" IS NULL) = ("points" IS NULL)
        AND ("answered_at" IS NULL) = ("is_correct" IS NULL)
        AND ("answered_at" IS NULL) = ("fraction" IS NULL)),
    ADD CONSTRAINT "game_answers_answer_is_object" CHECK ("answer" IS NULL OR jsonb_typeof("answer") = 'object');

-- question_bank
ALTER TABLE "question_bank"
    ADD CONSTRAINT "question_bank_code_format" CHECK ("code" ~ '^[a-z0-9][a-z0-9_.-]*$'),
    ADD CONSTRAINT "question_bank_category_format" CHECK ("category" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "question_bank_subcategory_format" CHECK ("subcategory" IS NULL OR "subcategory" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "question_bank_question_type_valid" CHECK ("question_type" IN (
        'SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'MAP_IDENTIFICATION', 'COUNTRY_IDENTIFICATION',
        'OBJECT_IDENTIFICATION', 'MATCHING', 'TRUE_FALSE', 'GEO_RELATIONSHIP', 'RESOURCE_IDENTIFICATION')),
    ADD CONSTRAINT "question_bank_answer_mode_valid" CHECK ("answer_mode" IN ('options', 'map_single', 'map_multi', 'pairs')),
    ADD CONSTRAINT "question_bank_difficulty_range" CHECK ("difficulty" BETWEEN 1 AND 3),
    ADD CONSTRAINT "question_bank_base_points_range" CHECK ("base_points" BETWEEN 0 AND 10000),
    ADD CONSTRAINT "question_bank_time_limit_positive" CHECK ("time_limit_sec" IS NULL OR "time_limit_sec" > 0),
    ADD CONSTRAINT "question_bank_data_year_range" CHECK ("data_year" IS NULL OR "data_year" BETWEEN 1800 AND 2200),
    ADD CONSTRAINT "question_bank_language_format" CHECK ("language" ~ '^[a-z]{2,3}(-[A-Za-z0-9]+)*$'),
    ADD CONSTRAINT "question_bank_verification_status_valid" CHECK ("verification_status" IN ('draft', 'in_review', 'verified', 'rejected')),
    ADD CONSTRAINT "question_bank_origin_valid" CHECK ("origin" IN ('curated', 'ai_generated', 'imported')),
    ADD CONSTRAINT "question_bank_version_positive" CHECK ("version" >= 1),
    ADD CONSTRAINT "question_bank_options_shape" CHECK (jsonb_typeof("options") IN ('array', 'object')),
    ADD CONSTRAINT "question_bank_correct_answers_is_array" CHECK (jsonb_typeof("correct_answers") = 'array'),
    ADD CONSTRAINT "question_bank_map_is_object" CHECK ("map" IS NULL OR jsonb_typeof("map") = 'object'),
    ADD CONSTRAINT "question_bank_fact_ref_is_object" CHECK ("fact_ref" IS NULL OR jsonb_typeof("fact_ref") = 'object'),
    -- A verified question records who verified it and when.
    ADD CONSTRAINT "question_bank_verified_is_reviewed" CHECK (
        "verification_status" <> 'verified' OR ("reviewed_by" IS NOT NULL AND "reviewed_at" IS NOT NULL));

-- data_sources, countries
ALTER TABLE "data_sources"
    ADD CONSTRAINT "data_sources_code_format" CHECK ("code" ~ '^[a-z][a-z0-9_]*$');
ALTER TABLE "countries"
    ADD CONSTRAINT "countries_code_format" CHECK ("code" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "countries_wikidata_id_format" CHECK ("wikidata_id" IS NULL OR "wikidata_id" ~ '^Q[0-9]+$');

-- geo_objects
ALTER TABLE "geo_objects"
    ADD CONSTRAINT "geo_objects_code_format" CHECK ("code" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "geo_objects_object_type_format" CHECK ("object_type" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "geo_objects_lat_range" CHECK ("lat" IS NULL OR "lat" BETWEEN -90 AND 90),
    ADD CONSTRAINT "geo_objects_lon_range" CHECK ("lon" IS NULL OR "lon" BETWEEN -180 AND 180),
    ADD CONSTRAINT "geo_objects_lat_lon_together" CHECK (("lat" IS NULL) = ("lon" IS NULL)),
    ADD CONSTRAINT "geo_objects_geometry_ref_complete" CHECK (("geometry_layer" IS NULL) = ("geometry_feature_id" IS NULL)),
    ADD CONSTRAINT "geo_objects_bbox_is_array" CHECK ("bbox" IS NULL OR jsonb_typeof("bbox") = 'array'),
    ADD CONSTRAINT "geo_objects_properties_is_object" CHECK (jsonb_typeof("properties") = 'object'),
    ADD CONSTRAINT "geo_objects_wikidata_id_format" CHECK ("wikidata_id" IS NULL OR "wikidata_id" ~ '^Q[0-9]+$'),
    ADD CONSTRAINT "geo_objects_data_year_range" CHECK ("data_year" IS NULL OR "data_year" BETWEEN 1800 AND 2200),
    ADD CONSTRAINT "geo_objects_verification_status_valid" CHECK ("verification_status" IN ('draft', 'in_review', 'verified', 'rejected'));

-- geo_object_countries, geo_object_links
ALTER TABLE "geo_object_countries"
    ADD CONSTRAINT "geo_object_countries_relation_format" CHECK ("relation" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "geo_object_countries_verification_status_valid" CHECK ("verification_status" IN ('draft', 'in_review', 'verified', 'rejected'));
ALTER TABLE "geo_object_links"
    ADD CONSTRAINT "geo_object_links_relation_format" CHECK ("relation" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "geo_object_links_not_self" CHECK ("object_id" <> "related_object_id"),
    ADD CONSTRAINT "geo_object_links_verification_status_valid" CHECK ("verification_status" IN ('draft', 'in_review', 'verified', 'rejected'));

-- country_resource_stats
ALTER TABLE "country_resource_stats"
    -- Production, reserves and resources are different things; never mix them.
    ADD CONSTRAINT "country_resource_stats_metric_valid" CHECK ("metric" IN ('mine_production', 'reserves', 'identified_resources')),
    ADD CONSTRAINT "country_resource_stats_value_non_negative" CHECK ("value" >= 0),
    ADD CONSTRAINT "country_resource_stats_rank_positive" CHECK ("rank" IS NULL OR "rank" >= 1),
    ADD CONSTRAINT "country_resource_stats_data_year_range" CHECK ("data_year" BETWEEN 1800 AND 2200),
    ADD CONSTRAINT "country_resource_stats_verification_status_valid" CHECK ("verification_status" IN ('draft', 'in_review', 'verified', 'rejected'));

-- ---------------------------------------------------------------------------
-- Trigger: a round is answered exactly once, and only while its session is
-- in progress. Together with UNIQUE (session_id, round_index) this makes
-- duplicate submissions and double scoring impossible even if the API
-- had a bug.
-- ---------------------------------------------------------------------------
CREATE FUNCTION "game_answers_answer_once"() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    session_status "game_session_status";
BEGIN
    IF OLD."answered_at" IS NOT NULL THEN
        RAISE EXCEPTION 'round % of session % is already answered', OLD."round_index", OLD."session_id"
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."answered_at" IS NOT NULL THEN
        SELECT "status" INTO session_status FROM "game_sessions" WHERE "id" = NEW."session_id";
        IF session_status <> 'in_progress' THEN
            RAISE EXCEPTION 'session % is %, rounds can only be answered while it is in progress',
                NEW."session_id", session_status
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    -- What was served (question, version, correct answers, multiplier) never changes.
    IF NEW."session_id" IS DISTINCT FROM OLD."session_id" OR NEW."round_index" IS DISTINCT FROM OLD."round_index"
       OR NEW."question_id" IS DISTINCT FROM OLD."question_id" OR NEW."question_version" IS DISTINCT FROM OLD."question_version"
       OR NEW."correct_answers" IS DISTINCT FROM OLD."correct_answers" OR NEW."score_multiplier" IS DISTINCT FROM OLD."score_multiplier"
       OR NEW."presented_at" IS DISTINCT FROM OLD."presented_at" THEN
        RAISE EXCEPTION 'round % of session %: only the answer may be recorded', OLD."round_index", OLD."session_id"
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER "game_answers_answer_once"
    BEFORE UPDATE ON "game_answers"
    FOR EACH ROW EXECUTE FUNCTION "game_answers_answer_once"();

-- ---------------------------------------------------------------------------
-- Trigger: the v2 scoring snapshot of a session is fixed once written.
-- level_id / score_multiplier / scoring_rules / rounds_planned may go from
-- NULL to a value (in the INSERT), never change afterwards. Pre-v2 sessions
-- keep NULL forever, so their history is never reinterpreted.
-- ---------------------------------------------------------------------------
CREATE FUNCTION "game_sessions_scoring_is_final"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."level_id" IS DISTINCT FROM OLD."level_id"
       OR NEW."score_multiplier" IS DISTINCT FROM OLD."score_multiplier"
       OR NEW."scoring_rules" IS DISTINCT FROM OLD."scoring_rules"
       OR NEW."rounds_planned" IS DISTINCT FROM OLD."rounds_planned" THEN
        RAISE EXCEPTION 'game session %: level and scoring rules cannot change after the session started', OLD."id"
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER "game_sessions_scoring_is_final"
    BEFORE UPDATE OF "level_id", "score_multiplier", "scoring_rules", "rounds_planned" ON "game_sessions"
    FOR EACH ROW EXECUTE FUNCTION "game_sessions_scoring_is_final"();
